const labelMap = {
  topic: '专题评估',
  comprehensive: '综合评估',
  party_self: '党性自评',
  party_review: '党性复评'
};
const rows = (ctx.data && ctx.data.objects) || [];
const data = rows.map(function (r) {
  return { name: labelMap[r.kind] || r.kind, value: Number(r.evalCount) || 0 };
});
return {
  tooltip: { trigger: 'item' },
  legend: { bottom: 0 },
  series: [
    { type: 'pie', radius: '62%', name: '评估记录分布', data: data, label: { formatter: '{b}: {c}' } }
  ]
};
